{
  "selections": [
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data", "/situations/3"],
      "relevance": "내담자가 '제가 아니게 되는 것 같다'고 말한 것은 자기희생 스키마로 인해 타인을 돌보는 역할에 과도하게 몰입한 결과, 자기 자신을 잃어버린 느낌을 경험하고 있음을 시사함. 성장 경험에서 '남을 돌볼 때만 가치 있다'는 신념이 형성된 것이, 배우자가 '당신은 뭘 원하는지 모르겠다'고 물었을 때 아무 대답을 하지 못한 상황과 연결됨."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "'제가 아니게 되는 것 같다'는 표현은 '나를 앞세우는 것은 이기적인 일'이라는 핵심신념이 내면화된 결과, 자기 욕구나 정체성 자체를 탐색할 기회조차 없었음을 반영함. 성장 경험에서 자기 것을 요구하면 '이기적이다'라는 핀잔을 받은 것이 이 신념의 근원임."
    },
    {
      "trait_id": "/core_belief/schema_definition",
      "background_ids": ["/situations/3"],
      "relevance": "'자기 욕구를 주장하면 죄책감을 느끼고, 돌봄을 받는 것보다 주는 역할에만 익숙함'이라는 정의가, '제가 아니게 된다'는 표현에서 자기 만족을 희생한 채 타인에게만 집중해온 삶의 패턴을 설명함. 배우자의 질문에 답하지 못한 것이 이를 구체적으로 보여줌."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/childhood_data"],
      "relevance": "'내 필요나 힘듦을 앞세우는 것은 이기적이고 부끄러운 일'이라는 태도가, 자신의 상태를 돌아볼 수 없게 만들어 '내가 누구인지'를 알 수 없게 하는 기제가 됨. 성장 경험에서 반복된 '이기적이다'라는 핀잔이 이 태도를 강화함."
    },
    {
      "trait_id": "/coping_strategies/4",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 '요즘 자꾸 제가 아니게 되는 것 같다'고 말한 맥락에는, 쌓인 피로와 서운함이 폭발(아이에게 소리 지름)한 후 죄책감으로 더 헌신하는 악순환이 포함되어 있음. 가족 모임에서 '너는 원래 잘하니까'라며 당연하게 맡겨지는 상황이 서운함을 누적시키는 예시임."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/2"],
      "relevance": "'괜찮아요, 별거 아니에요'로 자기 상태를 숨기는 전략이 반복되면, 정작 자기 내면을 들여다볼 기회를 갖지 못해 '제가 아니게 되는' 느낌을 강화함. 친구의 고민을 두 시간 넘게 들어주면서도 자기 이야기는 한마디도 하지 않은 상황이 이를 보여줌."
    }
  ]
}

